import{G as e,W as t,n,rt as r}from"./chunks/framework.CJ3GlOSn.js";var i=JSON.parse(`{"title":"Image","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/image.md","filePath":"03-developer/models/image.md"}`),a={name:`03-developer/models/image.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="image" tabindex="-1">Image <a class="header-anchor" href="#image" aria-label="Permalink to “Image”">​</a></h1><p>Manages images in a gallery. Each record is associated with a gallery and a user, and stores information such as the image&#39;s display title and order. The image file is managed through the Media Library.</p><h2 id="images-table" tabindex="-1"><code>images</code> table <a class="header-anchor" href="#images-table" aria-label="Permalink to “images table”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique image ID</td></tr><tr><td><code>gallery_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>ID of the associated gallery; associated with the <code>galleries</code> table</td></tr><tr><td><code>user_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>ID of the associated user; associated with the <code>users</code> table</td></tr><tr><td><code>title</code></td><td>TEXT</td><td>Yes</td><td>Image title or caption</td></tr><tr><td><code>sort</code></td><td>INT UNSIGNED</td><td>No</td><td>Image display order; defaults to <code>0</code></td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Creation date</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Date of last update</td></tr></tbody></table><h2 id="properties-and-methods" tabindex="-1">Properties and methods <a class="header-anchor" href="#properties-and-methods" aria-label="Permalink to “Properties and methods”">​</a></h2><h3 id="translatable" tabindex="-1"><code>$translatable</code> <a class="header-anchor" href="#translatable" aria-label="Permalink to “$translatable”">​</a></h3><p>The <code>title</code> field supports storing and retrieving translations.</p><h3 id="guarded" tabindex="-1"><code>$guarded</code> <a class="header-anchor" href="#guarded" aria-label="Permalink to “$guarded”">​</a></h3><p>An empty array (<code>[]</code>) means that no fields in the model are explicitly protected from mass assignment. Therefore, inputs should be properly validated and controlled when using <code>create()</code> or <code>fill()</code>.</p><h3 id="gallery" tabindex="-1"><code>gallery()</code> <a class="header-anchor" href="#gallery" aria-label="Permalink to “gallery()”">​</a></h3><p>Defines a <code>belongsTo</code> relationship with the <a href="./gallery.html">Gallery</a> model and returns the gallery associated with the image.</p><h3 id="registermediaconversions-media-media-null-void" tabindex="-1"><code>registerMediaConversions(Media $media = null): void</code> <a class="header-anchor" href="#registermediaconversions-media-media-null-void" aria-label="Permalink to “registerMediaConversions(Media $media = null): void”">​</a></h3><p>Defines the image&#39;s media conversions and optimizations:</p><ul><li><code>image-image</code>: Converts and optimizes the image.</li><li><code>githumb</code>: Creates a thumbnail with dimensions configured through <code>gallery_thumb</code>; the image is cropped and optimized, and its format is taken from the <code>optimize</code> settings.</li><li>If the <code>watermark</code> setting is enabled, a logo watermark is applied to the thumbnail, with configurable position, size, and opacity.</li></ul><p>The <code>githumb</code> conversion is defined with <code>nonQueued()</code> so it is processed without being added to the media processing queue.</p><h3 id="imgurl" tabindex="-1"><code>imgurl()</code> <a class="header-anchor" href="#imgurl" aria-label="Permalink to “imgurl()”">​</a></h3><p>Retrieves the image thumbnail URL from the Media Library. If no media exists for the model, it returns the site&#39;s default logo URL.</p><h3 id="imgoriginalurl" tabindex="-1"><code>imgOriginalUrl()</code> <a class="header-anchor" href="#imgoriginalurl" aria-label="Permalink to “imgOriginalUrl()”">​</a></h3><p>Returns the URL of the original version of the first media item associated with the model. If no media exists, the site&#39;s default logo URL is returned.</p>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};